import {readFileSync} from 'node:fs';import {createHash,webcrypto} from 'node:crypto';import vm from 'node:vm';import assert from 'node:assert/strict';
import {bundledVisualBindings as pins,bundledVisualReviewSha256 as reviewSHA} from '../../src/lib/bundled-visuals.js';
import {serveBundledVisual} from '../../../../server/fia/preparation/bundled-visual-publication.mjs';
const review=JSON.parse(readFileSync('../../server/fia/preparation/bundled-visual-review.json')),origin='https://fia.test',hash=b=>createHash('sha256').update(b).digest('hex'),rowsFor=id=>review.rows.filter(r=>r.packId===id),manifestFor=(f,g=reviewSHA)=>({packId:f.visualPublication.packId,presentationRevision:f.visualPublication.presentationRevision,deliveryRevision:g});
export function bundledVisualHarness({classic=false,corrupt=false,defaultPack=false}={}){
 const pin=defaultPack?pins.find(f=>f.visualPublication.bindingKind==='approved-default'&&f.visualPublication.assetId==='a112'):pins[0],p=pin.visualPublication,handlers={},stores=new Map(),calls=[];let offline=false;
 const open=async name=>{if(!stores.has(name))stores.set(name,new Map());const store=stores.get(name);return {match:async key=>store.get(String(key))?.clone(),put:async(key,value)=>store.set(String(key),new Response(await value.arrayBuffer(),{status:value.status,headers:value.headers})),delete:async key=>store.delete(String(key)),keys:async()=>[...store.keys()],addAll:async()=>{}};};
 const shell='saved shell',audio='existing audio',generation='a'.repeat(64),base={schema:1,...manifestFor(pin),revision:'bundled-client-test',files:[{path:'/index.html',group:'core',bytes:shell.length,sha256:hash(shell)}]};delete base.deliveryRevision;if(classic){base.deliveryRevision=generation;base.files.push({path:'/audio/classic.opus',group:'audio',bytes:audio.length,sha256:hash(audio),mime:'audio/ogg',sourceSha256:hash(audio),sourceBytes:audio.length,deliveryRevision:generation,deliveryURL:'https://transcode.klappy.dev/audio/preset=voice,q=medium,f=opus/https://source.invalid/audio.mp3'});}
 const env={FIA_API_ORIGIN:origin,ASSETS:{async fetch(request){const path=new URL(request.url).pathname;assert.ok(path.startsWith('/assets/mark-1-1-13/'));const bytes=readFileSync('public'+path);return new Response(bytes,{headers:{'Content-Type':path.endsWith('.png')?'image/png':'image/jpeg','Content-Length':String(bytes.length)}});}}},options={currentRevision:id=>rowsFor(id)[0]?.revision,currentPresentation:async id=>({revision:rowsFor(id)[0]?.revision,assets:Object.fromEntries(rowsFor(id).map(r=>[r.assetId,r.asset]))})};
 const fetcher=async input=>{const url=new URL(typeof input==='string'?input:input.url,origin);calls.push(url.href);if(offline)throw new TypeError('offline');if(url.pathname===`/offline/${p.packId}.json`)return Response.json(base);if(url.pathname.startsWith('/v1/verified-visuals/'))return new Response('not admitted',{status:404});if(url.pathname.startsWith('/v1/bundled-visuals/')){const response=await serveBundledVisual(new Request(url),env,options);if(corrupt&&url.pathname===new URL(pin.deliveryURL,origin).pathname)return new Response(new Uint8Array(pin.bytes),{headers:{'Content-Type':pin.mime}});return response;}if(url.pathname==='/index.html')return new Response(shell);if(url.origin==='https://transcode.klappy.dev')return new Response(audio,{headers:{'Content-Type':'audio/ogg'}});return new Response('missing',{status:404});};
 const context=vm.createContext({self:{addEventListener:(type,fn)=>handlers[type]=fn,location:{origin},clients:{claim:async()=>{}}},caches:{open,keys:async()=>[...stores.keys()],delete:async n=>stores.delete(n)},fetch:fetcher,Response,Request,Headers,URL,crypto:webcrypto,console,AbortController,setTimeout,clearTimeout,TextEncoder,TextDecoder,permittedRecordings:f=>f,recordingAllowed:()=>true,generatedRecordingPaths:[]});const sources=['src/lib/media-delivery.js','src/lib/proxy-request.js','src/lib/bundled-visuals.js'].map(path=>readFileSync(path,'utf8').replace(/export /g,''));vm.runInContext(sources.join('\n')+'\n'+readFileSync('public/sw.js','utf8').replace('__BUILD_ID__','test'),context);
 return {pin,calls,context,offline:v=>offline=v,async message(type,extra={}){let result,pending;handlers.message({data:{type,packId:p.packId,...extra},source:{id:'fixture'},ports:[{postMessage:value=>{if(!value.progress)result=value;}}],waitUntil:promise=>pending=promise});await pending;return result;}};
}
